cat > src/proxy.ts <<'EOF'
import { NextResponse, type NextRequest } from "next/server";
import { getSessionCookie } from "better-auth/cookies";

// Optimistic check only: it looks for the session cookie without validating it.
// The dashboard page itself verifies the session via requireUser().
export function proxy(request: NextRequest) {
  if (!getSessionCookie(request)) {
    return NextResponse.redirect(new URL("/sign-in", request.url));
  }
  return NextResponse.next();
}

export const config = {
  matcher: ["/dashboard/:path*"],
};
EOF
cat > src/lib/users.ts <<'EOF'
import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { auth } from "@/lib/auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type AuthUser = { id: string; email: string; name: string; createdAt: Date };

function toUser(u: AuthUser): User {
  return {
    id: u.id,
    email: u.email,
    name: u.name,
    createdAt: new Date(u.createdAt).toISOString().slice(0, 10),
  };
}

export async function listUsers(): Promise<User[]> {
  const ctx = await auth.$context;
  const users = await ctx.internalAdapter.listUsers(undefined, undefined, {
    field: "createdAt",
    direction: "asc",
  });
  return users.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const ctx = await auth.$context;
  const user = await ctx.internalAdapter.findUserById(id);
  return user ? toUser(user) : undefined;
}

export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  return session ? toUser(session.user) : undefined;
}

// For pages that must not render without a signed-in user.
export async function requireUser(): Promise<User> {
  const user = await getCurrentUser();
  if (!user) redirect("/sign-in");
  return user;
}
EOF
