cat > src/components/auth-form.tsx <<'EOF'
"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { authClient } from "@/lib/auth-client";

type Mode = "sign-in" | "sign-up";

const inputClass =
  "w-full rounded border border-black/15 bg-transparent px-3 py-2 text-sm dark:border-white/20";
const buttonClass =
  "w-full rounded bg-foreground px-3 py-2 text-sm font-medium text-background disabled:opacity-50";

export function AuthForm({ mode }: { mode: Mode }) {
  const router = useRouter();
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);

  async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const email = String(form.get("email"));
    const password = String(form.get("password"));

    setPending(true);
    setError(null);
    const { error } =
      mode === "sign-up"
        ? await authClient.signUp.email({ name: String(form.get("name")), email, password })
        : await authClient.signIn.email({ email, password });
    setPending(false);

    if (error) {
      setError(error.message ?? "Something went wrong.");
      return;
    }
    router.push("/dashboard");
    router.refresh();
  }

  async function onGoogle() {
    setPending(true);
    setError(null);
    const { error } = await authClient.signIn.social({
      provider: "google",
      callbackURL: "/dashboard",
    });
    if (error) {
      setPending(false);
      setError(error.message ?? "Google sign-in is unavailable.");
    }
  }

  return (
    <main className="mx-auto w-full max-w-sm p-8">
      <h1 className="text-2xl font-semibold">
        {mode === "sign-up" ? "Create your Notely account" : "Sign in to Notely"}
      </h1>

      <form onSubmit={onSubmit} className="mt-6 space-y-3">
        {mode === "sign-up" && (
          <input name="name" placeholder="Name" required className={inputClass} />
        )}
        <input
          name="email"
          type="email"
          placeholder="Email"
          autoComplete="email"
          required
          className={inputClass}
        />
        <input
          name="password"
          type="password"
          placeholder="Password"
          autoComplete={mode === "sign-up" ? "new-password" : "current-password"}
          minLength={8}
          required
          className={inputClass}
        />
        <button type="submit" disabled={pending} className={buttonClass}>
          {mode === "sign-up" ? "Sign up" : "Sign in"}
        </button>
      </form>

      <button
        type="button"
        onClick={onGoogle}
        disabled={pending}
        className="mt-3 w-full rounded border border-black/15 px-3 py-2 text-sm font-medium disabled:opacity-50 dark:border-white/20"
      >
        Continue with Google
      </button>

      {error && (
        <p role="alert" className="mt-4 text-sm text-red-600">
          {error}
        </p>
      )}

      <p className="mt-6 text-sm opacity-70">
        {mode === "sign-up" ? (
          <>
            Already have an account? <Link href="/sign-in" className="underline">Sign in</Link>
          </>
        ) : (
          <>
            New to Notely? <Link href="/sign-up" className="underline">Create an account</Link>
          </>
        )}
      </p>
    </main>
  );
}
EOF
