# Copy to .env.local and fill in real values.

# Secret used to sign session cookies. Generate one with: openssl rand -base64 32
BETTER_AUTH_SECRET=replace-with-a-random-32-byte-secret
# Public URL of the app (used for OAuth callbacks and CSRF origin checks).
BETTER_AUTH_URL=http://localhost:3000

# SQLite file for users and sessions (created on first start).
DATABASE_PATH=notely.db

# Google OAuth client (https://console.cloud.google.com/apis/credentials).
# Authorized redirect URI: http://localhost:3000/api/auth/callback/google
GOOGLE_CLIENT_ID=your-google-client-id.apps.googleusercontent.com
GOOGLE_CLIENT_SECRET=your-google-client-secret
EOF
cat >> .gitignore <<'EOF'
!.env.example

# local sqlite database
*.db
*.db-*
EOF
cp .env.example .env.local && sed -i '' "s|^BETTER_AUTH_SECRET=.*|BETTER_AUTH_SECRET=$(openssl rand -base64 32)|" .env.local
