input.command:
cat > src/lib/auth-options.ts <<'EOF'
import { DatabaseSync } from "node:sqlite";
import type { BetterAuthOptions } from "better-auth";
import { nextCookies } from "better-auth/next-js";

// Reuse one connection across dev hot reloads.
const globalForDb = globalThis as unknown as { notelyDb?: DatabaseSync };
const db = (globalForDb.notelyDb ??= new DatabaseSync(
  process.env.DATABASE_PATH ?? "notely.db",
));

const googleClientId = process.env.GOOGLE_CLIENT_ID;
const googleClientSecret = process.env.GOOGLE_CLIENT_SECRET;

// Kept apart from the auth instance so instrumentation.ts can migrate the
// schema before betterAuth() runs its own schema check.
export const authOptions = {
  database: db,
  emailAndPassword: {
    enabled: true,
    minPasswordLength: 8,
  },
  socialProviders:
    googleClientId && googleClientSecret
      ? { google: { clientId: googleClientId, clientSecret: googleClientSecret } }
      : {},
  // Must stay last so it can set cookies from server actions.
  plugins: [nextCookies()],
} satisfies BetterAuthOptions;
EOF
cat > src/lib/auth.ts <<'EOF'
import { betterAuth } from "better-auth";
import { authOptions } from "@/lib/auth-options";

export const auth = betterAuth(authOptions);
EOF
cat > src/instrumentation.ts <<'EOF'
// Creates or updates the auth tables once on server start.
export async function register() {
  if (process.env.NEXT_RUNTIME === "nodejs") {
    const { getMigrations } = await import("better-auth/db/migration");
    const { authOptions } = await import("@/lib/auth-options");
    const { runMigrations } = await getMigrations(authOptions);
    await runMigrations();
  }
}
EOF
npx tsc --noEmit && npm run lint && rm -f notely.db* && npm run build 2>&1 | grep -i "error\|mismatch\|✓ Compiled"

